package com.cloudinfra.sdk.native

import java.nio.{ByteBuffer, ByteOrder}
import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import java.util.concurrent.ConcurrentHashMap
import scala.util.{Try, Success, Failure}

object NativeAccelerator {
  System.loadLibrary("cloudinfra_native")

  @native def nativeEncrypt(input: Array[Byte], keyHandle: Long, outputBuf: ByteBuffer): Int
  @native def nativeDecrypt(input: Array[Byte], keyHandle: Long, outputBuf: ByteBuffer): Int
  @native def allocateKeyHandle(keyMaterial: Array[Byte]): Long
  @native def releaseKeyHandle(handle: Long): Unit
}

sealed trait CircuitState
case object Closed extends CircuitState
case object Open extends CircuitState
case object HalfOpen extends CircuitState

class CircuitBreaker(
  val failureThreshold: Int = 5,
  val resetTimeoutMs: Long = 30000,
  val halfOpenMaxCalls: Int = 3
) {
  private val failureCount = new AtomicInteger(0)
  private val lastFailureTime = new AtomicLong(0)
  private val halfOpenCalls = new AtomicInteger(0)
  @volatile private var state: CircuitState = Closed

  def currentState: CircuitState = {
    state match {
      case Open if System.currentTimeMillis() - lastFailureTime.get() > resetTimeoutMs =>
        state = HalfOpen
        halfOpenCalls.set(0)
        HalfOpen
      case s => s
    }
  }

  def recordSuccess(): Unit = {
    state match {
      case HalfOpen =>
        if (halfOpenCalls.incrementAndGet() >= halfOpenMaxCalls) {
          state = Closed
          failureCount.set(0)
        }
      case _ => failureCount.set(0)
    }
  }

  def recordFailure(): Unit = {
    lastFailureTime.set(System.currentTimeMillis())
    if (failureCount.incrementAndGet() >= failureThreshold) {
      state = Open
    }
  }

  def allowRequest: Boolean = currentState != Open
}

class NativeCryptoService(circuitBreaker: CircuitBreaker) {
  private val handleCache = new ConcurrentHashMap[String, Long]()
  private val bufferPool = new ThreadLocal[ByteBuffer] {
    override def initialValue(): ByteBuffer = 
      ByteBuffer.allocateDirect(65536).order(ByteOrder.nativeOrder())
  }

  def getOrCreateHandle(keyId: String, keyMaterial: Array[Byte]): Long = {
    handleCache.computeIfAbsent(keyId, _ => {
      NativeAccelerator.allocateKeyHandle(keyMaterial)
    })
  }

  def encrypt(keyId: String, keyMaterial: Array[Byte], plaintext: Array[Byte]): Try[Array[Byte]] = {
    if (!circuitBreaker.allowRequest) {
      Failure(new RuntimeException("Circuit breaker is open"))
    } else {
      try {
        val handle = getOrCreateHandle(keyId, keyMaterial)
        val outputBuffer = bufferPool.get()
        outputBuffer.clear()

        val resultLen = NativeAccelerator.nativeEncrypt(plaintext, handle, outputBuffer)

        if (resultLen < 0) {
          circuitBreaker.recordFailure()
          Failure(new RuntimeException(s"Native encryption failed: $resultLen"))
        } else {
          circuitBreaker.recordSuccess()
          outputBuffer.flip()
          val result = new Array[Byte](resultLen)
          outputBuffer.get(result)
          Success(result)
        }
      } catch {
        case e: Exception =>
          circuitBreaker.recordFailure()
          Failure(e)
      }
    }
  }

  def decrypt(keyId: String, keyMaterial: Array[Byte], ciphertext: Array[Byte]): Try[Array[Byte]] = {
    if (!circuitBreaker.allowRequest) {
      Failure(new RuntimeException("Circuit breaker is open"))
    } else {
      try {
        val handle = getOrCreateHandle(keyId, keyMaterial)
        val outputBuffer = bufferPool.get()
        outputBuffer.clear()

        val resultLen = NativeAccelerator.nativeDecrypt(ciphertext, handle, outputBuffer)

        if (resultLen < 0) {
          circuitBreaker.recordFailure()
          Failure(new RuntimeException(s"Native decryption failed: $resultLen"))
        } else {
          circuitBreaker.recordSuccess()
          outputBuffer.flip()
          val result = new Array[Byte](resultLen)
          outputBuffer.get(result)
          Success(result)
        }
      } catch {
        case e: Exception =>
          circuitBreaker.recordFailure()
          Failure(e)
      }
    }
  }

  def invalidateHandle(keyId: String): Unit = {
    val handle = handleCache.remove(keyId)
    if (handle != null) {
      NativeAccelerator.releaseKeyHandle(handle)
    }
  }

  def rotateKey(keyId: String, newKeyMaterial: Array[Byte]): Try[Long] = {
    try {
      val oldHandle = handleCache.get(keyId)
      val newHandle = NativeAccelerator.allocateKeyHandle(newKeyMaterial)
      handleCache.put(keyId, newHandle)
      // Release old handle after replacing in cache
      if (oldHandle != 0L) {
        NativeAccelerator.releaseKeyHandle(oldHandle)
      }
      Success(newHandle)
    } catch {
      case e: Exception =>
        circuitBreaker.recordFailure()
        Failure(e)
    }
  }
}
